/**
 * SAMPLE DISCOVERIES — illustrative only.
 *
 * Hand-written examples of the four discovery types ASTRION is designed to surface. Evidence items
 * paraphrase the fictional sample sources in ./graph.ts. These are NOT research findings and were
 * NOT generated by a model.
 */
export type DiscoveryType = 'relationship' | 'contradiction' | 'gap' | 'hypothesis';
export type VerificationStatus = 'unverified' | 'in_review' | 'conditional' | 'verified' | 'refuted';

export interface EvidenceItem {
  id: string;
  sourceId: string;
  sourceLabel: string;
  locator: string;
  statement: string;
  stance: 'supports' | 'contradicts' | 'context';
  extraction: 'manual-sample';
}

export interface Discovery {
  id: string;
  type: DiscoveryType;
  title: string;
  summary: string;
  evidenceIds: string[];
  conceptIds: string[];
  status: VerificationStatus;
  /** Qualitative confidence band — sample values, not computed. */
  confidence: 'low' | 'moderate' | 'high';
  nextStep: string;
}

